 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seeds = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 2]
    q = deque(seeds)
    seen = set(seeds)
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and out[nr][nc] == 0:
                seen.add((nr,nc))
                out[nr][nc] = 2
                q.append((nr,nc))
    return out
